 static byte[] normalizeDex(byte[] data,byte[] base,byte[] patch)throws Exception{for(byte[] input:new byte[][]{base,patch})if(input.length<112||input[0]!='d'||input[1]!='e'||input[2]!='x'||input[3]!=10||input[4]!='0'||input[5]!='3'||input[6]!='5'||input[7]!=0)throw new IOException("La fusión requiere entradas DEX035.");if(data.length<112||data[0]!='d'||data[1]!='e'||data[2]!='x'||data[3]!=10||data[4]!='0'||data[5]!='3'||(data[6]!='5'&&data[6]!='6')||data[7]!=0)throw new IOException("Versión DEX de salida desconocida.");java.nio.ByteBuffer header=java.nio.ByteBuffer.wrap(data).order(java.nio.ByteOrder.LITTLE_ENDIAN);if(header.getInt(32)!=data.length||header.getInt(36)!=112||header.getInt(40)!=0x12345678)throw new IOException("Cabecera DEX inválida.");for(int at:new int[]{64,72,80,88})if(header.getInt(at)<0||header.getInt(at)>65535)throw new IOException("Índices DEX excedidos.");int offset=header.getInt(52);if(offset<112||offset>data.length-4)throw new IOException("Mapa DEX inválido.");int count=header.getInt(offset);if(count<1||count>32||offset+4L+count*12L>data.length)throw new IOException("Mapa DEX fuera de límites.");for(int i=0;i<count;i++){int type=header.getShort(offset+4+i*12)&65535;if(!((type>=0&&type<=6)||(type>=0x1000&&type<=0x1003)||(type>=0x2000&&type<=0x2006)))throw new IOException("Sección no compatible con DEX035.");}byte[] result=data.clone();result[6]='5';byte[] digest=java.security.MessageDigest.getInstance("SHA-1").digest(java.util.Arrays.copyOfRange(result,32,result.length));System.arraycopy(digest,0,result,12,20);java.util.zip.Adler32 checksum=new java.util.zip.Adler32();checksum.update(result,12,result.length-12);java.nio.ByteBuffer.wrap(result).order(java.nio.ByteOrder.LITTLE_ENDIAN).putInt(8,(int)checksum.getValue());return result;}
 static JSONObject translated(JSONObject snapshot,JSONObject before)throws Exception{JSONObject next=new JSONObject(snapshot.toString());Iterator<String> it=before.keys();while(it.hasNext()){String name=it.next();if(!next.has(name))next.put(name,before.getString(name));}return next;}
 static synchronized void sync(Context c)throws Exception{SharedPreferences p=DeviceApk.prefs(c),j=JavaProject.prefs(c);String to=p.getString("coreTo","");if(to.isEmpty()||!to.equals(JavaProject.fingerprint(c))||!j.getString("base","").equals(p.getString("coreFrom",""))||!j.getString("working","{}").equals(p.getString("coreWork","")))return;JSONObject before=new JSONObject(p.getString("coreBefore","{}")),backup=new JSONObject().put("base",j.getString("base","")).put("working",j.getString("working","{}")).put("accepted",j.getString("accepted","{}")).put("history",j.getString("history","[]"));JSONArray old=new JSONArray(j.getString("history","[]")),history=new JSONArray();for(int i=0;i<old.length();i++)history.put(translated(old.getJSONObject(i),before));if(!j.edit().putString("previousBase",backup.toString()).putString("base",to).putString("working","{}").putString("accepted",translated(new JSONObject(j.getString("accepted","{}")),before).toString()).putString("history",history.toString()).putInt("revision",j.getInt("revision",0)+1).remove("compiledHash").commit())throw new IOException("No pude sincronizar las fuentes instaladas.");}
 static String graph(Context c,String file)throws Exception{Map<String,byte[]> data=classes(baseline(c));if(JavaProject.prefs(c).contains("base")){String hash=ProjectRuntime.workspace(c);if(!hash.equals(JavaProject.prefs(c).getString("compiledHash","")))JavaProject.compile(c);if(!hash.equals(JavaProject.prefs(c).getString("compiledHash","")))throw new IOException("La copia no compila.");data=new TreeMap<>();File[] files=new File(JavaProject.prefs(c).getString("build",""),"classes/com/bananalab/lite").listFiles();if(files!=null)for(File f:files)try(InputStream in=new FileInputStream(f)){data.put("com/bananalab/lite/"+f.getName(),OnDeviceJava.bytes(in,1000000));}}int classes=0,methods=0,refs=0,eligible=0;StringBuilder out=new StringBuilder("Dependencias del bytecode compilado\n");for(Map.Entry<String,byte[]> e:data.entrySet()){JvmClass cls=JvmClass.read(e.getValue());classes++;methods+=cls.methods.size();refs+=cls.calls.size();if(!cls.desugar)eligible++;if(file!=null&&e.getKey().equals("com/bananalab/lite/"+file.replace(".java",".class"))){out.append(file).append(" · ").append(cls.methods.size()).append(" métodos · requiere desugaring: ").append(cls.desugar).append('\n');int i=0;for(String call:cls.calls)if(i++<30)out.append(call).append('\n');}}return out.append(classes).append(" clases, ").append(methods).append(" métodos, ").append(refs).append(" referencias simbólicas; ").append(eligible).append(" clases sin desugaring. No es una resolución completa del despacho virtual ni una prueba del comportamiento.").toString();}
